from collections import deque

# BFS to find the level of each node
def bfs(graph, start):
    level = {start: 0}
    queue = deque([start])
    while queue:
        node = queue.popleft()
        for neighbor in graph[node]:
            if neighbor not in level:
                level[neighbor] = level[node] + 1
                queue.append(neighbor)
    return level

